// Gravrust WASM module - generated by wasm-bindgen (minimal version for boot)

// This module is loaded by main.js to access the Rust/WASM core
// The actual WASM module is loaded via initSync with base64-encoded bytes

let wasmModule = null;
let wasmInitialized = false;

export function initSync(options) {
    if (wasmInitialized) {
        console.warn('[gravrust] WASM already initialized');
        return;
    }
    
    if (!options || !options.module) {
        throw new Error('WASM module bytes required');
    }
    
    // The actual WASM instantiation happens in the browser
    // This is a minimal stub - the real instantiation happens via WebAssembly.instantiate
    if (typeof WebAssembly !== 'undefined' && WebAssembly.instantiate) {
        WebAssembly.instantiate(options.module, {})
            .then(instance => {
                wasmModule = instance.exports;
                wasmInitialized = true;
                console.log('[gravrust] WASM module instantiated');
            })
            .catch(err => {
                console.error('[gravrust] WASM instantiation failed:', err);
            });
    } else {
        console.error('[gravrust] WebAssembly not supported');
    }
}

export function core_version() {
    return '0.2.0';
}

export function boot(settings, device, assets) {
    // The actual boot function is called from main.js after WASM init
    // This is a placeholder - the real boot is in the WASM module
    return Promise.resolve();
}

export function start_game_loop() {
    // Start the game loop - called after boot completes
    console.log('[gravrust] Game loop started (stub)');
}

export function init_wasm() {
    // One-time setup hook
    console.log('[gravrust] init_wasm called');
}

export function reset_core() {
    console.log('[gravrust] reset_core called');
}

export const __wbg_init = initSync;
export const __wbg_boot = boot;
export const __wbg_start_game_loop = start_game_loop;

export default {
    initSync,
    core_version,
    boot,
    start_game_loop,
    init_wasm,
    reset_core,
    __wbg_init,
    __wbg_boot,
    __wbg_start_game_loop
};